def area_of_circle(radius):
    return 3.14 * radius * radius

print(area_of_circle(2))

numbers = [4, 8, 15, 16, 23, 42]

def linear_search(target):
    for index, value in enumerate(numbers):
        if value == target:
            return index
    return -1

print(linear_search(15))
print(linear_search(99))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))

let state = "idle";

function transition(event) {
  if (state === "idle" && event === "start") {
    state = "running";
  } else if (state === "running" && event === "stop") {
    state = "idle";
  }
}

transition("start");
console.log(state);
transition("stop");
console.log(state);

def average(numbers):
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)

print(average([]))
print(average([2, 4]))

def has_pair(numbers, target):
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if numbers[i] + numbers[j] == target:
                return True
    return False

print(has_pair([1, 2, 4, 7], 9))
print(has_pair([1, 2, 4, 7], 20))

def binary_search(sorted_numbers, target):
    low, high = 0, len(sorted_numbers) - 1
    while low <= high:
        middle = (low + high) // 2
        if sorted_numbers[middle] == target:
            return middle
        if sorted_numbers[middle] < target:
            low = middle + 1
        else:
            high = middle - 1
    return -1

print(binary_search([1, 3, 5, 7, 9], 7))
